1	use std::io;
2	
3	use utf8_zero::DecodeError;
4	
5	use crate::util::ConsumeBuf;
6	
7	const REPLACEMENT_CHAR: u8 = b'?';
8	const MIN_BUF: usize = 8;
9	
10	pub struct LossyUtf8Reader<R> {
11	    reader: R,
12	    ended: bool,
13	    input: ConsumeBuf,
14	    valid_len: usize,
15	}
16	impl<R> LossyUtf8Reader<R> {
17	    pub(crate) fn new(reader: R) -> Self {
18	        Self {
19	            reader,
20	            ended: false,
21	            input: ConsumeBuf::new(8),
22	            valid_len: 0,
23	        }
24	    }
25	
26	    fn process_input(&mut self) -> usize {
27	        match utf8_zero::decode(self.input.unconsumed()) {
28	            Ok(_) => {
29	                // Entire input is valid
30	                self.input.unconsumed().len()
31	            }
32	            Err(e) => match e {
33	                DecodeError::Invalid {
34	                    valid_prefix,
35	                    invalid_sequence,
36	                    ..
37	                } => {
38	                    let valid_len = valid_prefix.len();
39	                    let invalid_len = invalid_sequence.len();
40	
41	                    // Switch out the problem input chars
42	                    let replace_in = self.input.unconsumed_mut();
43	                    for i in 0..invalid_len {
44	                        replace_in[valid_len + i] = REPLACEMENT_CHAR;
45	                    }
46	
47	                    valid_len + invalid_len
48	                }
49	                DecodeError::Incomplete { valid_prefix, .. } => {
50	                    let valid_len = valid_prefix.len();
51	
52	                    if self.ended {
53	                        // blank the rest
54	                        let replace_in = self.input.unconsumed_mut();
55	                        let invalid_len = replace_in.len() - valid_len;
56	                        for i in 0..invalid_len {
57	                            replace_in[valid_len + i] = REPLACEMENT_CHAR;
58	                        }
59	                        valid_len + invalid_len
60	                    } else {
61	                        valid_len
62	                    }
63	                }
64	            },
65	        }
66	    }
67	}
68	
69	impl<R: io::Read> io::Read for LossyUtf8Reader<R> {
70	    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
