        let mut res = crate::get("https://my.test/nonempty").call().unwrap();
        let err = res
            .body_mut()
            .with_config()
            .limit(0)
            .read_to_string()
            .unwrap_err();
        assert!(matches!(err, Error::BodyExceedsLimit(0)));
    }

