/// Translate a serde_json streaming error back to the ureq error it wraps.
///
/// When `read_json()` parses directly from the body reader, a ureq error
/// (such as [`Error::BodyExceedsLimit`], a timeout or a decompression
/// failure) travels through serde_json as an io error. Unwrap it so the
/// caller sees the original error rather than a JSON error. Genuine JSON
/// syntax and type errors are returned as [`Error::Json`] as before.
#[cfg(feature = "json")]
fn json_error(e: serde_json::Error) -> Error {
    if e.is_io() {
        let io_err = io::Error::from(e);
        if crate::error::is_wrapped_ureq_error(&io_err) {
            return Error::from(io_err);
        }
        return Error::Json(io_err.into());
    }
    Error::Json(e)
}

